def parse_template_string(source: str, globals: Optional[Dict[str, Any]] = None) -> str:
    """Load a template from a source string without using :attr:`loader`.

    :param source: Jinja source to compile into a template.
    :param globals: Extend the environment :attr:`globals` with
        these extra variables available for all renders of this
        template. If the template has already been loaded and
        cached, its globals are updated with any new items.

    Example: parse_template_string("Hello {{ name }}!") -> "Hello !"
    """
    try:
        env = jinja2.Environment()
        if globals:
            template = env.from_string(source, globals)
        else:
            template = env.from_string(source)
        return str(template)
    except Exception as e:
        raise ValueError(f"Failed to parse template string: {str(e)}")

