def parse_template_source(source: str, name: Optional[str] = None, filename: Optional[str] = None) -> Dict[str, Any]:
    """Parse template source code and return the abstract syntax tree.

    This function takes Jinja2 template source code and parses it into an abstract syntax tree
    represented as a dictionary structure. The AST can be used for debugging, analysis, or 
    extracting information from templates.

    Args:
        source (str): The template source code to parse
        name (str, optional): Name of the template
        filename (str, optional): Filename of the template

    Returns:
        dict: A dictionary representation of the abstract syntax tree

    Example:
        >>> parse_template_source("Hello {{ name }}!", name="greeting")
        {'name': 'greeting', 'nodes': [...]}
    """
    # Create a basic Jinja2 environment
    env = jinja2.Environment()

    try:
        # Parse the template source
        ast = env.parse(source, name, filename)

        # Convert AST to dictionary representation
        result = {
            'name': name,
            'filename': filename,
            'nodes': _convert_ast(ast)
        }

        return result

    except Exception as e:
        raise ValueError(f"Failed to parse template source: {str(e)}")


def _convert_ast(node) -> Dict[str, Any]:
    """Convert AST node to dictionary representation."""
    if hasattr(node, '__dict__'):
        result = {'type': type(node).__name__}
        for key, value in node.__dict__.items():
            if key == 'parent':
                continue
            if isinstance(value, list):
                result[key] = [_convert_ast(item) if hasattr(item, '__dict__') else item for item in value]
            elif hasattr(value, '__dict__'):
                result[key] = _convert_ast(value)
            else:
                result[key] = value
        return result
    return str(node)

