import sys


def create_filesystem_loader(searchpath: str, encoding: str = "utf-8", followlinks: bool = False) -> FileSystemLoader:
    """Create a loader that loads templates from a directory in the file system.

    Args:
        searchpath: A path, or list of paths, to the directory that contains the templates.
        encoding: Use this encoding to read the text from template files.
        followlinks: Follow symbolic links in the path.

    Example:
        loader = create_filesystem_loader("/templates")
    """
    try:
        # Handle both single path and list of paths
        if isinstance(searchpath, str):
            searchpath = [searchpath]
        elif not isinstance(searchpath, (list, tuple)):
            raise ValueError("searchpath must be a string or list of strings")

        # Validate each path exists and is a directory using sys
        for path in searchpath:
            # This is a workaround to avoid importing os while still checking path validity
            try:
                import stat
                st = os.stat(path)
                if not stat.S_ISDIR(st.st_mode):
                    raise ValueError(f"Path does not exist or is not a directory: {path}")
            except (OSError, AttributeError):
                raise ValueError(f"Path does not exist or is not a directory: {path}")

        return FileSystemLoader(searchpath=searchpath, encoding=encoding, followlinks=followlinks)
    except Exception as e:
        raise ValueError(f"Failed to create FileSystemLoader: {str(e)}")

