def parse_expression(
    environment: object,
    source: str,
    name: str | None = None,
    filename: str | None = None,
    state: str | None = None,
    with_condexpr: bool = True,
) -> dict[str, str | int | list | None]:
    """Parse a single Jinja2 expression and return the corresponding AST node. environment: A Jinja2 Environment instance, source: The Jinja2 expression source code to parse, name: Name of the template, filename: Filename of the template, state: State of the template, with_condexpr: Whether to parse conditional expressions. Example: parse_expression(env, "x + y") -> {"type": "Add", "left": {...}, "right": {...}}."""
    try:
        parser = jinja2.environment.Parser(environment, source, name, filename, state)
        ast_node = parser.parse_expression(with_condexpr)

        # Convert AST node to dictionary representation
        def node_to_dict(node):
            if node is None:
                return None
            result = {"type": type(node).__name__}
            for key, value in node.__dict__.items():
                if key.startswith('_'):
                    continue
                if isinstance(value, nodes.Node):
                    result[key] = node_to_dict(value)
                elif isinstance(value, list):
                    result[key] = [node_to_dict(item) for item in value]
                else:
                    result[key] = value
            return result

        return node_to_dict(ast_node)
    except Exception as e:
        raise ValueError(f"Failed to parse expression: {str(e)}")

