def parse_assign_target(source: str, with_tuple: bool = True, name_only: bool = False, with_namespace: bool = False) -> Union[str, List[str], Dict[str, Any]]:
    """Parse an assignment target from Jinja template source. source: the Jinja template source code, with_tuple: whether to allow tuple assignment targets, name_only: whether to only allow simple name targets, with_namespace: whether to allow namespace assignment targets. Example: parse_assign_target('a = 1', name_only=True) -> 'a'."""

    try:
        # Create a parser instance
        env = jinja2.Environment()
        parser = Parser(env, source)

        # Parse the assignment target
        result = parser.parse_assign_target(
            with_tuple=with_tuple,
            name_only=name_only,
            with_namespace=with_namespace
        )

        # Convert the result to a JSON-serializable format
        if hasattr(result, 'name'):
            # It's a Name node
            return result.name
        elif hasattr(result, 'items'):
            # It's a Tuple node
            return [item.name if hasattr(item, 'name') else str(item) for item in result.items]
        elif hasattr(result, 'node') and hasattr(result, 'attr'):
            # It's an NSRef node (namespace reference)
            return f"{result.node.name}.{result.attr}"
        else:
            # Fallback - convert to string representation
            return str(result)

    except Exception as e:
        raise ValueError(f"Failed to parse assignment target: {str(e)}")

