from typing import Union, Dict, Any


def parse_set_statement(source: str, environment: jinja2.Environment, name: str | None = None, filename: str | None = None) -> Dict[str, Any]:
    """Parse a Jinja2 set statement for variable assignment.

    Args:
        source: The Jinja2 template source code containing the set statement to parse
        environment: A Jinja2 Environment object for parsing
        name: Name of the template (optional)
        filename: Filename of the template (optional)

    Returns:
        Dictionary representation of the parsed assignment node with keys 'type', 'target', and 'value'
        For Assign nodes: {'type': 'Assign', 'target': str, 'value': str}
        For AssignBlock nodes: {'type': 'AssignBlock', 'target': str, 'filter': str, 'body': list[str]}

    Example:
        parse_set_statement('set x = 1', env) -> {'type': 'Assign', 'target': 'x', 'value': '1'}
    """
    try:
        parser = jinja2.environment.Parser(environment, source, name, filename)
        result = parser.parse_set()

        if isinstance(result, jinja2.nodes.Assign):
            return {
                'type': 'Assign',
                'target': str(result.target),
                'value': str(result.node)
            }
        elif isinstance(result, jinja2.nodes.AssignBlock):
            return {
                'type': 'AssignBlock',
                'target': str(result.target),
                'filter': str(result.filter) if result.filter else None,
                'body': [str(node) for node in result.body]
            }
        else:
            raise ValueError(f"Unexpected node type: {type(result)}")

    except Exception as e:
        raise ValueError(f"Failed to parse set statement: {str(e)}") from e

