def parse_filter(
    environment: object, source: str, expression: str
) -> dict[str, str | int | None] | None:
    """Parse a Jinja2 filter application on an expression and return the filtered AST node. environment: A Jinja2 Environment instance, source: The template source string to parse, expression: The expression to parse and apply filters to. Example: parse_filter(env, 'Hello {{ name|upper }}', 'name|upper') -> {'type': 'Filter', 'name': 'upper'}."""
