def describe_token_expression(expr: str) -> str:
    """Returns a human-readable description of a token expression used in the lexer. expr: A token expression string, e.g. 'name:foo' -> 'foo'."""
    if ":" in expr:
        type_, value = expr.split(":", 1)

        if type_ == jinja2.lexer.TOKEN_NAME:
            return value
    else:
